import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import Button from 'flarum/common/components/Button';
const t = (key, params) => app.translator.trans(`jslirola-registration-policy.forum.pending_confirmation.${key}`, params);

/**
 * Shown on the page that loads right after a sign-up that did not sign the
 * visitor in, so a reload into a guest page is never the only feedback.
 */
export default class PendingConfirmationModal extends Modal {
  className() {
    return 'Modal--small PendingConfirmationModal';
  }
  title() {
    return t('title');
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "Form Form--centered"
    }, m("p", {
      className: "helpText"
    }, t('text', {
      email: m("strong", null, this.attrs.email)
    })), m("p", {
      className: "helpText"
    }, t('spam_hint')), m("div", {
      className: "Form-group"
    }, m(Button, {
      className: "Button Button--primary Button--block",
      onclick: () => this.hide()
    }, t('close_button')))));
  }
}
flarum.reg.add('jslirola-registration-policy', 'forum/components/PendingConfirmationModal', PendingConfirmationModal);